import{_ as e,c as d,o,b2 as a}from"./chunks/framework.CUhoHPxN.js";const m=JSON.parse('{"title":"权限管理","description":"","frontmatter":{},"headers":[],"relativePath":"docs/backend/modules/permission-management.md","filePath":"docs/backend/modules/permission-management.md"}'),r={name:"docs/backend/modules/permission-management.md"};function c(l,t,s,n,i,h){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="权限管理" tabindex="-1">权限管理 <a class="header-anchor vp-link" href="#权限管理" aria-label="Permalink to &quot;权限管理&quot;">​</a></h1><p>权限由 <strong>菜单（路由+按钮）</strong>、<strong>角色</strong>、<strong>用户-角色</strong> 与 <strong>数据权限</strong> 共同组成，基于 Sa-Token 注解与前端 <code>perms</code> 字符串。</p><h2 id="菜单管理" tabindex="-1">菜单管理 <a class="header-anchor vp-link" href="#菜单管理" aria-label="Permalink to &quot;菜单管理&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysMenuController</code></td></tr><tr><td>路径</td><td><code>/system/menu</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>菜单列表（树形）</td></tr><tr><td>GET <code>/treeselect</code></td><td>下拉树</td></tr><tr><td>GET <code>/roleMenuTreeselect/{roleId}</code></td><td>角色已选菜单树</td></tr><tr><td>GET <code>/{menuId}</code></td><td>详情</td></tr><tr><td>POST <code>/update</code></td><td>新增/修改（按 Bo 分组）</td></tr><tr><td>POST <code>/remove/{menuId}</code></td><td>删除</td></tr></tbody></table></div><p>菜单字段要点：</p><ul><li><code>menuType</code>：目录 M / 菜单 C / 按钮 F</li><li><code>perms</code>：按钮权限标识，前端 <code>v-hasPermi</code> 使用</li><li><code>component</code>：前端组件路径，如 <code>system/user/index</code></li><li><code>path</code>、<code>query</code>：路由 path 与参数</li></ul><p>登录后 <code>GET /getRouters</code> 将菜单转为前端路由（见 <a href="./../../frontend/router.html" class="vp-link">前端路由配置</a>）。</p><h2 id="角色管理" tabindex="-1">角色管理 <a class="header-anchor vp-link" href="#角色管理" aria-label="Permalink to &quot;角色管理&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>值</th></tr></thead><tbody><tr><td>Controller</td><td><code>SysRoleController</code></td></tr><tr><td>路径</td><td><code>/system/role</code></td></tr><tr><td>前端</td><td><code>views/system/role/index.vue</code></td></tr></tbody></table></div><div class="vp-table"><table><thead><tr><th>接口</th><th>说明</th></tr></thead><tbody><tr><td>GET <code>/list</code></td><td>角色分页</td></tr><tr><td>POST <code>/create</code>、<code>/update</code>、<code>/remove</code></td><td>CRUD</td></tr><tr><td>POST <code>/changeStatus</code></td><td>状态</td></tr><tr><td>POST <code>/dataScope</code></td><td><strong>数据权限</strong>范围</td></tr><tr><td>POST <code>/menu</code></td><td>保存角色菜单</td></tr><tr><td>GET <code>/authUser/allocatedList</code>、<code>unallocatedList</code></td><td>角色下已/未分配用户</td></tr><tr><td>POST <code>/authUser/selectAll</code>、<code>cancel</code>、<code>cancelAll</code></td><td>批量授权/取消</td></tr><tr><td>POST <code>/export</code>、<code>/import</code>、<code>/import/template</code></td><td>Excel</td></tr></tbody></table></div><h3 id="数据权限类型-datascope" tabindex="-1">数据权限类型（dataScope） <a class="header-anchor vp-link" href="#数据权限类型-datascope" aria-label="Permalink to &quot;数据权限类型（dataScope）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>值</th><th>含义</th></tr></thead><tbody><tr><td>1</td><td>全部数据</td></tr><tr><td>2</td><td>自定义部门</td></tr><tr><td>3</td><td>本部门</td></tr><tr><td>4</td><td>本部门及以下</td></tr><tr><td>5</td><td>仅本人</td></tr></tbody></table></div><h2 id="用户角色" tabindex="-1">用户角色 <a class="header-anchor vp-link" href="#用户角色" aria-label="Permalink to &quot;用户角色&quot;">​</a></h2><p>在用户管理中 <code>authRole</code> 接口维护；角色侧也可反向分配用户。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor vp-link" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="./user-management.html" class="vp-link">用户管理</a></li><li><a href="./../api/permission.html" class="vp-link">权限接口</a></li></ul>',17)])])}const u=e(r,[["render",c]]);export{m as __pageData,u as default};
